/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { FabryPerotScreen } from "../../src/fabry-perot/FabryPerotScreen.js";
import InterferometryLabColors from "../../src/InterferometryLabColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { MachZehnderScreen } from "../../src/mach-zehnder/MachZehnderScreen.js";
import { MichelsonScreen } from "../../src/michelson/MichelsonScreen.js";
import { InterferometryLabPreferencesModel } from "../../src/preferences/InterferometryLabPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from interferometryLabQueryParameters.
  const simPreferences = new InterferometryLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new MichelsonScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().michelsonStringProperty,
      tandem: Tandem.ROOT.createTandem("michelsonScreen"),
      backgroundColorProperty: InterferometryLabColors.backgroundColorProperty,
    }),
    new MachZehnderScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().machZehnderStringProperty,
      tandem: Tandem.ROOT.createTandem("machZehnderScreen"),
      backgroundColorProperty: InterferometryLabColors.backgroundColorProperty,
    }),
    new FabryPerotScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().fabryPerotStringProperty,
      tandem: Tandem.ROOT.createTandem("fabryPerotScreen"),
      backgroundColorProperty: InterferometryLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { InterferometryLabColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
